// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// IssueDocumentLink Get a short-lived, single-use link to one document
	// (POST /v1/documents/{documentId}/links)
	IssueDocumentLink(ctx context.Context, request IssueDocumentLinkRequestObject) (IssueDocumentLinkResponseObject, error)
	// ReportDocumentProhibitedId Report that a document shows a prohibited identifier (an Aadhaar number in the India pack)
	// (POST /v1/documents/{documentId}/prohibited-id-report)
	ReportDocumentProhibitedId(ctx context.Context, request ReportDocumentProhibitedIdRequestObject) (ReportDocumentProhibitedIdResponseObject, error)
	// DownloadFile Download through a link (bound to the user who got it; works once)
	// (GET /v1/files/{token})
	DownloadFile(ctx context.Context, request DownloadFileRequestObject) (DownloadFileResponseObject, error)
	// ListAccessExtensionRequests Doctors who asked for more time on my shared history, waiting for my answer
	// (GET /v1/me/access-extension-requests)
	ListAccessExtensionRequests(ctx context.Context, request ListAccessExtensionRequestsRequestObject) (ListAccessExtensionRequestsResponseObject, error)
	// ApproveAccessExtension Allow the doctor more time (tier T4). Only this answer gives access
	// (POST /v1/me/access-extension-requests/{requestId}/approve)
	ApproveAccessExtension(ctx context.Context, request ApproveAccessExtensionRequestObject) (ApproveAccessExtensionResponseObject, error)
	// DeclineAccessExtension Say no to a doctor's request for more time
	// (POST /v1/me/access-extension-requests/{requestId}/decline)
	DeclineAccessExtension(ctx context.Context, request DeclineAccessExtensionRequestObject) (DeclineAccessExtensionResponseObject, error)
	// ListAccessGrants Who can see my record, and until when
	// (GET /v1/me/access-grants)
	ListAccessGrants(ctx context.Context, request ListAccessGrantsRequestObject) (ListAccessGrantsResponseObject, error)
	// RevokeAccessGrant Stop sharing (T3 and T4 only; T1 and T2 are kept by law)
	// (POST /v1/me/access-grants/{grantId}/revoke)
	RevokeAccessGrant(ctx context.Context, request RevokeAccessGrantRequestObject) (RevokeAccessGrantResponseObject, error)
	// ListAccessLog Who viewed my record and when (people only)
	// (GET /v1/me/access-log)
	ListAccessLog(ctx context.Context, request ListAccessLogRequestObject) (ListAccessLogResponseObject, error)
	// RequestAccountErasure Close my account and erase my data (step 1 at once; needs a fresh step-up)
	// (POST /v1/me/account-erasure)
	RequestAccountErasure(ctx context.Context, request RequestAccountErasureRequestObject) (RequestAccountErasureResponseObject, error)
	// UndoAccountErasure Undo an erasure inside the undo window
	// (POST /v1/me/account-erasure/{requestId}/undo)
	UndoAccountErasure(ctx context.Context, request UndoAccountErasureRequestObject) (UndoAccountErasureResponseObject, error)
	// ListConsents My current consent choices
	// (GET /v1/me/consents)
	ListConsents(ctx context.Context, request ListConsentsRequestObject) (ListConsentsResponseObject, error)
	// GrantConsent Give consent for one purpose (the text version shown)
	// (POST /v1/me/consents)
	GrantConsent(ctx context.Context, request GrantConsentRequestObject) (GrantConsentResponseObject, error)
	// WithdrawConsent Withdraw an optional purpose; takes effect immediately
	// (POST /v1/me/consents/{purposeId}/withdraw)
	WithdrawConsent(ctx context.Context, request WithdrawConsentRequestObject) (WithdrawConsentResponseObject, error)
	// RequestDataExport Ask for a full copy of my records (needs a fresh step-up)
	// (POST /v1/me/data-exports)
	RequestDataExport(ctx context.Context, request RequestDataExportRequestObject) (RequestDataExportResponseObject, error)
	// ListDocuments My uploaded documents
	// (GET /v1/me/documents)
	ListDocuments(ctx context.Context, request ListDocumentsRequestObject) (ListDocumentsResponseObject, error)
	// UploadDocument Upload a PDF, JPEG or PNG (type checked by content, scanned, encrypted)
	// (POST /v1/me/documents)
	UploadDocument(ctx context.Context, request UploadDocumentRequestObject) (UploadDocumentResponseObject, error)
	// DeleteMyDocument Delete one of my uploads
	// (DELETE /v1/me/documents/{documentId})
	DeleteMyDocument(ctx context.Context, request DeleteMyDocumentRequestObject) (DeleteMyDocumentResponseObject, error)
	// CreateHistoryShare Share my history with one verified doctor for one confirmed appointment (P-SHARE screen)
	// (POST /v1/me/history-shares)
	CreateHistoryShare(ctx context.Context, request CreateHistoryShareRequestObject) (CreateHistoryShareResponseObject, error)
	// ListRightsRequests My data-rights requests and their status
	// (GET /v1/me/rights-requests)
	ListRightsRequests(ctx context.Context, request ListRightsRequestsRequestObject) (ListRightsRequestsResponseObject, error)
	// CreateRightsRequest See my data, ask for a correction or name a nominee (data-rights-flows §2)
	// (POST /v1/me/rights-requests)
	CreateRightsRequest(ctx context.Context, request CreateRightsRequestRequestObject) (CreateRightsRequestResponseObject, error)
	// GetRightsRequest Status of one request, with the erasure report once known
	// (GET /v1/me/rights-requests/{requestId})
	GetRightsRequest(ctx context.Context, request GetRightsRequestRequestObject) (GetRightsRequestResponseObject, error)
	// IssueExportLink Get a single-use link to download my finished export
	// (POST /v1/me/rights-requests/{requestId}/export-link)
	IssueExportLink(ctx context.Context, request IssueExportLinkRequestObject) (IssueExportLinkResponseObject, error)
	// RequestAccessExtension Ask the patient for more time on a shared history that is ending or has ended
	// (POST /v1/patients/{patientId}/access-extension-requests)
	RequestAccessExtension(ctx context.Context, request RequestAccessExtensionRequestObject) (RequestAccessExtensionResponseObject, error)
	// ListPatientDocuments The documents the patient uploaded, for a doctor with an active history share
	// (GET /v1/patients/{patientId}/documents)
	ListPatientDocuments(ctx context.Context, request ListPatientDocumentsRequestObject) (ListPatientDocumentsResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

